<?php

namespace App\Enums;

use Filament\Support\Contracts\HasColor;
use Filament\Support\Contracts\HasLabel;

enum TipoImputazione: string implements HasLabel, HasColor
{
    case Nido = 'nido';
    case Materna = 'materna';
    case Primavera = 'primavera';

    public function getLabel(): string
    {
        return match ($this) {
            self::Nido => 'Nido',
            self::Materna => 'Materna',
            self::Primavera => 'Primavera',
        };
    }

    public function getColor(): string|array|null
    {
        return match ($this) {
            self::Nido => 'info',
            self::Materna => 'success',
            self::Primavera => 'warning',
        };
    }
}

